def _buffered_generator(self, size: int) -> t.Iterator[str]:
    buf: t.List[str] = []
    c_size = 0
    push = buf.append

    while True:
        try:
            while c_size < size:
                c = next(self._gen)
                push(c)
                if c:
                    c_size += 1
        except StopIteration:
            if not c_size:
                return
        yield concat(buf)
        del buf[:]
        c_size = 0

